answers.combine-two-tables:
SELECT p.firstName, p.lastName, a.city, a.state
FROM Person p
LEFT JOIN Address a ON p.personId = a.personId;

answers.find-customer-referee:
SELECT name
FROM Customer
WHERE referee_id IS NULL OR referee_id <> 2;

answers.big-countries:
SELECT name, population, area
FROM World
WHERE area >= 3000000 OR population >= 25000000;

answers.triangle-judgement:
SELECT x, y, z,
  CASE WHEN x + y > z AND x + z > y AND y + z > x THEN 'Yes' ELSE 'No' END AS triangle
FROM Triangle;

answers.game-play-analysis-i:
SELECT player_id, MIN(event_date) AS first_login
FROM Activity
GROUP BY player_id;

answers.recyclable-and-low-fat-products:
SELECT product_id
FROM Products
WHERE low_fats = 'Y' AND recyclable = 'Y';

answers.invalid-tweets:
SELECT tweet_id
FROM Tweets
WHERE LENGTH(content) > 15;

answers.fix-names-in-a-table:
SELECT user_id, CONCAT(UPPER(LEFT(name, 1)), LOWER(SUBSTRING(name, 2))) AS name
FROM Users
ORDER BY user_id;

answers.find-total-time-spent-by-each-employee:
SELECT event_day AS day, emp_id, SUM(out_time - in_time) AS total_time
FROM Employees
GROUP BY event_day, emp_id;

answers.daily-leads-and-partners:
SELECT date_id, make_name, COUNT(DISTINCT lead_id) AS unique_leads, COUNT(DISTINCT partner_id) AS unique_partners
FROM DailySales
GROUP BY date_id, make_name;

answers.replace-employee-id-with-the-unique-iden:
SELECT eu.unique_id, e.name
FROM Employees e
LEFT JOIN EmployeeUNI eu ON e.id = eu.id;

answers.find-users-with-valid-e-mails:
SELECT user_id, name, mail
FROM Users
WHERE mail REGEXP '^[A-Za-z][A-Za-z0-9_.-]*@leetcode[.]com$';

answers.patients-with-a-condition:
SELECT patient_id, patient_name, conditions
FROM Patients
WHERE conditions LIKE 'DIAB1%' OR conditions LIKE '% DIAB1%';

answers.product-sales-analysis-i:
SELECT p.product_name, s.year, s.price
FROM Sales s
JOIN Product p ON s.product_id = p.product_id;

answers.biggest-single-number:
SELECT MAX(num) AS num
FROM (
  SELECT num FROM MyNumbers GROUP BY num HAVING COUNT(*) = 1
) t;

answers.number-of-unique-subjects-taught-by-each:
SELECT teacher_id, COUNT(DISTINCT subject_id) AS cnt
FROM Teacher
GROUP BY teacher_id;

answers.second-highest-salary:
SELECT (
  SELECT DISTINCT salary FROM Employee ORDER BY salary DESC LIMIT 1 OFFSET 1
) AS SecondHighestSalary;

answers.department-highest-salary:
SELECT d.name AS Department, e.name AS Employee, e.salary AS Salary
FROM Employee e
JOIN Department d ON e.departmentId = d.id
WHERE (e.departmentId, e.salary) IN (
  SELECT departmentId, MAX(salary) FROM Employee GROUP BY departmentId
);

answers.product-price-at-a-given-date:
SELECT p.product_id, COALESCE(
  (SELECT new_price FROM Products WHERE product_id = p.product_id AND change_date <= '2019-08-16' ORDER BY change_date DESC LIMIT 1),
  10
) AS price
FROM (SELECT DISTINCT product_id FROM Products) p;

answers.capital-gainloss:
SELECT stock_name, SUM(CASE WHEN operation = 'Sell' THEN price ELSE -price END) AS capital_gain_loss
FROM Stocks
GROUP BY stock_name;

answers.product-sales-analysis-iii:
SELECT product_id, year AS first_year, quantity, price
FROM Sales
WHERE (product_id, year) IN (SELECT product_id, MIN(year) FROM Sales GROUP BY product_id);

answers.immediate-food-delivery-ii:
SELECT ROUND(AVG(order_date = customer_pref_delivery_date) * 100, 2) AS immediate_percentage
FROM Delivery
WHERE (customer_id, order_date) IN (
  SELECT customer_id, MIN(order_date) FROM Delivery GROUP BY customer_id
);
